WITH cleaned AS (SELECT id, supplier_name, city, rating, SUBSTRING(city, 1, 2) AS city_prefix, CASE WHEN rating >= 3.5 THEN 'High' WHEN rating >= 1.8 THEN 'Medium' ELSE 'Low' END AS rating_band FROM suppliers WHERE city IS NOT NULL AND city IS DISTINCT FROM 'Tokyo') SELECT s.id, s.rating, latest.stock_qty FROM cleaned s JOIN LATERAL (SELECT c.stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.launch_date DESC, c.id DESC LIMIT 1) latest ON TRUE
